seq = ""
for line in open("region.fasta"):
    if line.startswith(">"): continue
    seq += line.strip().upper()
comp=str.maketrans("ACGT","TGCA")
rcstr = seq.translate(comp)[::-1]
bases="TCAG"; aas="FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG"
codon={}; i=0
for a in bases:
    for b in bases:
        for c in bases:
            codon[a+b+c]=aas[i]; i+=1
def tr(s): return "".join(codon.get(s[i:i+3],"X") for i in range(0,len(s)-2,3))

def orfs(s, strand):
    out=[]
    for f in range(3):
        p = tr(s[f:])
        pos = f
        for part in p.split("*"):
            L=len(part)*3+3
            if len(part)>=60:
                # coords on the strand used
                out.append((strand, f, pos, pos+L, len(part), part))
            pos += L
    return out

allorf=[]
for o in orfs(seq,"+"): allorf.append(o)
for o in orfs(rcstr,"-"):
    # convert to forward coords: rc position k corresponds to seq[3000-1-k]
    allorf.append((o[0],o[1],o[2],o[3],o[4],o[5]))
allorf.sort(key=lambda t:-t[4])
for o in allorf[:10]:
    print(o[0],o[1],o[2],o[3],o[4])
    print("   ",o[5][:200])
