# direct repeats: find duplicated k-mers with distance 300..2600
for k in (9,10,12,14,20):
    pos={}
    for i in range(n-k+1):
        pos.setdefault(seq[i:i+k],[]).append(i)
    pairs=[]
    for w,locs in pos.items():
        if len(locs)>1:
            for a in range(len(locs)):
                for b in range(a+1,len(locs)):
                    d=locs[b]-locs[a]
                    if 250<d<2700:
                        pairs.append((k,d,locs[a],locs[b],w))
    print("k=",k,"n=",len(pairs))
    for p in pairs[:10]:
        print("   ",p)
